+// Till sales: each dish sold uses one portion of its recipe per unit sold.
+// A ticket is imported once; importing is all or nothing (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sales from `lines` ({ row, ticket, soldAt, dishId, qty }, already
+ * checked for shape). Tickets imported before are skipped. Checks every line
+ * first, then consumes stock with ref `sale:<ticket>`. Throws bad_request or
+ * sale_not_enough_stock naming the row, and then changes nothing.
+ */
+export function importSales(store, lines) {
+  const tickets = new Map();
+  for (const l of lines) {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    let t = tickets.get(l.ticket);
+    if (!t) {
+      t = { ticket: l.ticket, soldAt: l.soldAt, lines: [] };
+      tickets.set(l.ticket, t);
+    } else if (t.soldAt !== l.soldAt) {
+      throw new AppError("bad_request", { reason: `row ${l.row}: soldAt differs from earlier rows of ticket ${l.ticket}` });
+    }
+    t.lines.push({ ...l, recipe: getRecipe(store, dish.recipeId) });
+  }
+
+  // Check stock for every new ticket, in file order, before changing anything.
+  const fresh = [...tickets.values()].filter((t) => !hasTicket(store, t.ticket));
+  const need = new Map();
+  for (const t of fresh) {
+    t.uses = new Map();
+    for (const l of t.lines) {
+      for (const n of scaled(l.recipe, l.qty)) {
+        const item = getItem(store, n.itemId);
+        const total = round3((need.get(n.itemId) ?? 0) + n.qty);
+        const available = round3(onHand(store, n.itemId));
+        if (total > available)
+          throw new AppError("sale_not_enough_stock", { row: l.row, item: item.name, available, unit: item.unit });
+        need.set(n.itemId, total);
+        t.uses.set(n.itemId, round3((t.uses.get(n.itemId) ?? 0) + n.qty));
+      }
+    }
+  }
+
+  // Safety net: if consuming still fails (rounding), restore the stock.
+  const before = { batches: structuredClone(store.data.batches), movements: store.data.movements.length, seq: { ...store.data.seq } };
+  try {
+    store.data.sales ??= [];
+    for (const t of fresh) {
+      for (const [itemId, qty] of t.uses) if (qty > 0) consume(store, itemId, qty, { at: t.soldAt, ref: `sale:${t.ticket}` });
+      store.data.sales.push({
+        id: store.nextId("sale"),
+        ticket: t.ticket,
+        soldAt: t.soldAt,
+        lines: t.lines.map((l) => ({ dishId: l.dishId, qty: l.qty })),
+        uses: [...t.uses].map(([itemId, qty]) => ({ itemId, qty })),
+      });
+    }
+  } catch (e) {
+    store.data.batches = before.batches;
+    store.data.movements.length = before.movements;
+    store.data.seq = before.seq;
+    store.data.sales = (store.data.sales ?? []).filter((s) => !fresh.some((t) => t.ticket === s.ticket));
+    throw e;
+  }
+  return { tickets: fresh.length, dishes: fresh.reduce((s, t) => s + t.lines.reduce((x, l) => x + l.qty, 0), 0) };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold on those days, actual use from every consume movement, and the
+ * difference (actual − theoretical). Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    for (const u of s.uses) row(u.itemId).theoretical += u.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  return [...rows.values()]
+    .map((r) => {
+      const theoretical = round3(r.theoretical);
+      const actual = round3(r.actual);
+      return { itemId: r.itemId, theoretical, actual, difference: round3(actual - theoretical) };
+    })
+    .filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
